head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > selectedRowColor]<br/>현재 포커스된 Row 의 배경색으로 적용될 색상을 설정합니다. focusMode='row','both' 인 경우에 동작합니다.",
    "validation" : [
        "현재 포커스된 Row 의 배경색으로 적용될 색상을 설정합니다. focusMode='row','both' 인 경우에 동작합니다.",
        "현재 포커스된 Row 의 배경색은 색상이름('blue','red'), 색상코드('#rrggbb'), 함수형('rgb(...)','rgba(...)') 등 다양한 형식으로 설정할 수 있습니다.",
        "selectedRowColor 는 Row 의 disabled/readOnly 상태와 무관하게 포커스된 Row 에 동일 적용됩니다(포커스 배경색이 readOnly/disabled 배경색보다 나중 적용되어 우선).",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정 (con_ 옵션을 properties 객체로 모아 createCList 로 속성 문자열 생성, 빈값 자동 제외)
    //  - selectedRowColor 는 색상이름/코드/rgb/rgba 다양한 형식의 정적 select 값(미설정 포함)
    //  - focusMode 는 row 고정 (selectedRowColor 가 동작하는 모드)
    //  - disabledBackgroundColor / readOnlyBackgroundColor : 비포커스 상태에서 disabled/readOnly Row 가
    //    일반 Row 와 구분되는 배경색으로 보이도록 설정 (포커스 시 selectedRowColor 가 우선 적용됨을 대비 관찰)
    let properties = {
        selectedRowColor        : con_selectedRowColor.getValue(),
        focusMode               : "row",
        disabledBackgroundColor : "#d9d9d9",
        readOnlyBackgroundColor : "#fff2cc"
    };
    let cList = $c.gcm.createCList(properties);

    // 이벤트 바인딩은 createEList 공통 함수 사용
    //  - oncellclick : 사용자가 Cell 을 클릭해 포커스가 이동하면 포커스된 Row 의 셀들 배경색을 출력
    let eList = $c.gcm.createEList(["oncellclick"]);

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    let lblRow = (properties.selectedRowColor === '') ? '미설정' : properties.selectedRowColor;
    $c.gcm.createLabel('label="selectedRowColor=' + lblRow + ' / focusMode=row 로 GridView 생성 (Row(1)=disabled→회색 #d9d9d9, Row(2)=readOnly→연노랑 #fff2cc). 셀을 클릭하면 포커스된 Row 의 셀들 배경색 출력"', '', 'label1');

    // dataList 생성 (column id 를 col1~col4 로 맞춤)
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');

    // target 생성 (disabled / readOnly row 포함 그리드 직접 구성 : Row0=normal, Row1=disabled, Row2=readOnly)
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' ' + eList + ' dataList="data:dlt_bind" checkAllType="false" id="" style="width:420px;height:280px;">';
    strTarget += '<w2:caption style="" id="caption1" value="selectedRowColor 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="100" style="" inputType="text" id="column1" value="name1"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="column2" value="name2"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="column3" value="name3"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="column4" value="name4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="100" style="" inputType="text" id="col1" value=""></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="col2" value=""></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="col3" value=""></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="col4" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

    // @spec disabled/readOnly 우선순위 검증용 사전상태 : Row(1)=disabled, Row(2)=readOnly
    target1.setRowDisabled(1, true);
    target1.setRowReadOnly(2, true);

    // 그리드 생성 직후, normal / disabled / readOnly Row 각각을 포커스하고
    // 포커스된 Row 의 computed 배경색을 자동 출력 (selectedRowColor 가 disabled/readOnly 보다 우선 적용됨을 자동으로 보여줌)
    scwin.showFocusedRowColor();
}



// 특정 Row(rowIndex) 의 각 셀 computed 배경색(rgb 형식) 을 합쳐 반환
//  - focusMode=row 에서는 포커스 시 Row 의 모든 셀(td) 에 selectedRowColor 가 적용되므로 셀별로 읽어 표시
scwin.getRowBgColor = function (rowIndex) {
    let colCnt = 4;
    let colors = [];
    for (let c = 0; c < colCnt; c++) {
        let td = document.querySelector("td[id*='mf_target1_cell_" + rowIndex + "_" + c + "']");
        colors.push("col" + c + "=" + (td ? window.getComputedStyle(td).backgroundColor : "(셀 없음)"));
    }
    return colors.join(" / ");
}



// oncellclick : 사용자가 Cell 을 마우스 왼쪽 버튼으로 클릭하면 발생 (클릭 시 해당 Row 로 포커스 이동)
//  - rowIndex / columnIndex / columnId : 클릭된 Cell 정보
//  - focusMode=row 이므로 클릭된 Cell 이 속한 Row 전체가 포커스되며, 그 Row 의 셀들 배경색을 출력 (selectedRowColor 적용 확인)
//  - 어떤 상태(normal/readOnly)의 Row 를 클릭했는지 라벨과 함께 출력
//  - (엔진 동작) disabled Row 는 클릭해도 oncellclick 이 발생하지 않으므로(이벤트 차단),
//    disabled Row 의 포커스 배경색은 Target 재생성 시 자동 출력(showFocusedRowColor) 으로 확인
scwin.target1_oncellclick = function (rowIndex, columnIndex, columnId) {
    // 클릭된 Row 의 상태 라벨 판별 (이 샘플 구성 : Row1=disabled, Row2=readOnly, 그 외 normal)
    let state = "normal";
    if (rowIndex === 1) {
        state = "disabled";
    } else if (rowIndex === 2) {
        state = "readOnly";
    }

    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_oncellclick=====");
    wf_body_bottom.getObj("scwin").setReturnValue("rowIndex : " + rowIndex + " / columnIndex : " + columnIndex + " / columnId : " + columnId);

    // 클릭에 의한 포커스 배경색 적용은 클릭 처리 직후 반영되므로 다음 tick 에서 read
    setTimeout(function () {
        let focusedColor = scwin.getRowBgColor(rowIndex);
        wf_body_bottom.getObj("scwin").setReturnValue("[클릭 포커스 " + state + " Row(" + rowIndex + ") 배경색] " + focusedColor);
    }, 0);
}



// "disabled Row 포커스 확인" 버튼 핸들러
//  - disabled Row(1) 는 클릭(oncellclick) 으로 포커스가 이동되지 않으므로(이벤트 차단),
//    setFocusedCell(1, 0) 으로 프로그래밍 방식 포커스를 이동한 뒤 해당 Row 의 셀 배경색을 출력
//  - selectedRowColor 가 disabled 배경색(#d9d9d9)보다 우선 적용됨을 온디맨드로 확인
scwin.btn_focusDisabledRow_onclick = function () {
    // 출력 전 clear
    wf_body_bottom.getObj("scwin").btn_clear_onclick();

    // disabled Row(1) 의 첫 번째 Cell 로 프로그래밍 포커스 이동
    target1.setFocusedCell(1, 0);

    wf_body_bottom.getObj("scwin").setReturnValue("=====btn_focusDisabledRow_onclick=====");
    wf_body_bottom.getObj("scwin").setReturnValue("setFocusedCell(1, 0) 호출 (disabled Row(1) 프로그래밍 포커스)");

    // 포커스 배경색 적용은 처리 직후 반영되므로 다음 tick 에서 read
    setTimeout(function () {
        let focusedColor = scwin.getRowBgColor(1);
        wf_body_bottom.getObj("scwin").setReturnValue("[프로그래밍 포커스 disabled Row(1) 배경색] " + focusedColor);
    }, 0);
}
